def axis(k, v, h, r, kind):
    from scipy.sparse import csc_matrix
    from scipy.sparse import diags
    n = len(k)
    face = (k[1:] + k[:-1]) / (2 * h * h)
    lo = -face - np.maximum(v[1:], 0) / h
    hi = -face - np.maximum(-v[:-1], 0) / h
    if kind in ('P', 'PR'):
        wrap = (k[0] + k[-1]) / (2 * h * h)
        wl = wrap + max(v[0], 0) / h
        wr = wrap + max(-v[-1], 0) / h
    else:
        wl = wr = 0.0
        hi[0] = -k[0] / h ** 2
        lo[-1] = -k[-1] / h ** 2
    diag = np.r_[-hi[0] + wl, -lo[:-1] - hi[1:], -lo[-1] + wr]
    if kind in ('R', 'PR', 'RN'):
        diag[[0, -1]] += r / h if kind != 'RN' else [r / h, 0.0]
    if kind == 'NR':
        diag[-1] += r / h
    if kind == 'D':
        diag[[0, -1]] += k[[0, -1]] / h ** 2
    return diags([lo, diag, hi], [-1, 0, 1], format='csc') + csc_matrix(([-wl, -wr], ([0, n - 1], [n - 1, 0])), shape=(n, n))
